UPDATE utb_role_mst
SET role_nm = #{roleNm},
    note = #{note},
    use_yn = #{useYn}
WHERE role_seq = #{roleSeq}

UPDATE utb_office_employee
SET    role_seq = #{roleSeq}
WHERE  user_mst_seq = #{userMstSeq}
  AND  office_seq   = #{officeSeq}
  AND  del_yn       = 'N'

UPDATE utb_office_employee
SET    role_seq = NULL
WHERE  user_mst_seq = #{userMstSeq}
  AND  office_seq   = #{officeSeq}
  AND  role_seq     = #{roleSeq}
  AND  del_yn       = 'N'

mapper.select:
SELECT COUNT(*) FROM utb_office_employee
WHERE  role_seq   = #{roleSeq}
  AND  office_seq = #{officeSeq}
  AND  del_yn     = 'N'

SELECT role_seq FROM utb_office_employee
WHERE  user_mst_seq = #{userMstSeq}
  AND  office_seq   = #{officeSeq}
  AND  del_yn       = 'N'
LIMIT 1
